import{_ as s,o as n,c as a,a2 as o}from"./chunks/framework.Di-jvWLj.js";const h=JSON.parse('{"title":"Triggers & the Envelope","description":"","frontmatter":{},"headers":[],"relativePath":"guide/triggers.md","filePath":"guide/triggers.md","lastUpdated":1792441266000}'),t={name:"guide/triggers.md"};function p(c,e,l,r,i,d){return n(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="triggers-the-envelope" tabindex="-1">Triggers &amp; the Envelope <a class="header-anchor" href="#triggers-the-envelope" aria-label="Permalink to &quot;Triggers &amp; the Envelope&quot;">​</a></h1><p>A trigger describes how a run of an agent can start. At intake every trigger becomes the same shape, a <code>TriggerEnvelope</code>, and <code>engine.dispatch()</code> turns the envelope into a <code>queued</code> run.</p><h2 id="trigger-definitions" tabindex="-1">Trigger definitions <a class="header-anchor" href="#trigger-definitions" aria-label="Permalink to &quot;Trigger definitions&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> triage = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Triage the issue in the trigger payload.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    triggers: [</span></span>
<span class="line"><span style="color:#E6DFDE;">        http(), </span><span style="color:#958A8B;">// id &#39;http&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">        webhook({ path: </span><span style="color:#E7C58C;">&#39;/issues&#39;</span><span style="color:#E6DFDE;"> }), </span><span style="color:#958A8B;">// id &#39;webhook:/issues&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">        cron(</span><span style="color:#E7C58C;">&#39;*/30 * * * *&#39;</span><span style="color:#E6DFDE;">, { overlap: </span><span style="color:#E7C58C;">&#39;skip&#39;</span><span style="color:#E6DFDE;"> }), </span><span style="color:#958A8B;">// id &#39;cron:*/30 * * * *&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Builder</th><th>Source</th><th>Id</th><th>Options</th></tr></thead><tbody><tr><td><code>http(opts?)</code></td><td><code>http</code></td><td><code>http</code></td><td><code>schema?</code>: a Standard Schema for the payload. At most one per agent; REST, the UI and MCP start runs through it</td></tr><tr><td><code>webhook(opts)</code></td><td><code>webhook</code></td><td><code>webhook:&lt;path&gt;</code></td><td><code>path</code> (starts with <code>/</code>), <code>schema?</code>, <code>idempotencyKey?</code>, <code>concurrencyKey?</code>. Many per agent</td></tr><tr><td><code>cron(expression, opts?)</code></td><td><code>cron</code></td><td><code>cron:&lt;expression&gt;</code></td><td><code>timezone?</code>, <code>overlap?</code> (<code>skip</code> by default, <code>queue-one</code>, <code>allow</code>), <code>payload?</code></td></tr></tbody></table><p><code>cron()</code> validates the expression (and timezone) with cron-parser and throws <code>InvalidAgentDefinitionError</code> for an invalid one; <code>webhook()</code> throws it for a path that does not start with <code>/</code>. Trigger ids must be unique per agent, so an agent declares <code>http()</code> at most once.</p><p>A <code>TriggerDefinition</code> may also carry <code>concurrencyKey(payload)</code> and <code>idempotencyKey(payload)</code> functions (<code>webhook()</code> copies them from its options). They are meant for the intake packages, which compute the envelope keys from a payload.</p><div class="warning custom-block"><p class="custom-block-title">Firing triggers is not in core</p><p>In <code>@chamberu/core</code>, <code>engine.dispatch()</code> is the only way a run starts. The trigger definitions describe intent; nothing in core fires a cron expression or listens on an HTTP path. <a href="/guide/scheduler"><code>@chamberu/scheduler</code></a> fires <code>cron()</code> triggers (with per-tick locks and the overlap policy); <a href="/guide/http"><code>@chamberu/http</code></a> serves <code>http()</code> triggers over REST and MCP and <code>webhook()</code> triggers at <code>/hooks/:agent&lt;path&gt;</code>.</p></div><h2 id="the-envelope" tabindex="-1">The envelope <a class="header-anchor" href="#the-envelope" aria-label="Permalink to &quot;The envelope&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">/*</span></span>
<span class="line"><span style="color:#958A8B;"> * Copyright (c) 2026.</span></span>
<span class="line"><span style="color:#958A8B;"> * Author Peter Placzek (tada5hi)</span></span>
<span class="line"><span style="color:#958A8B;"> * For the full copyright and license information,</span></span>
<span class="line"><span style="color:#958A8B;"> * view the LICENSE file that was distributed with this source code.</span></span>
<span class="line"><span style="color:#958A8B;"> */</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> TriggerSource = </span><span style="color:#E7C58C;">&#39;cron&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;http&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;github&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;mcp&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> TriggerDefinition&lt;P = unknown&gt; = {</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: TriggerSource;</span></span>
<span class="line"><span style="color:#958A8B;">    /** Unique within an agent, e.g. &#39;cron:*\\/30 * * * *&#39;. */</span></span>
<span class="line"><span style="color:#E6DFDE;">    id: string;</span></span>
<span class="line"><span style="color:#958A8B;">    /** Source-specific (cron: { expression, timezone?, overlap }). */</span></span>
<span class="line"><span style="color:#E6DFDE;">    options: Record&lt;string, unknown&gt;;</span></span>
<span class="line"><span style="color:#958A8B;">    // method signatures (bivariant): a TriggerDefinition&lt;P&gt; fits AgentDefinition.triggers</span></span>
<span class="line"><span style="color:#E6DFDE;">    concurrencyKey?(payload: P): string | undefined;</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey?(payload: P): string | undefined;</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> TriggerEnvelope&lt;P = unknown&gt; = {</span></span>
<span class="line"><span style="color:#E6DFDE;">    id: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    trigger: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: TriggerSource;</span></span>
<span class="line"><span style="color:#E6DFDE;">    payload: P;</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey?: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    concurrencyKey?: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    thread?: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    receivedAt: Date;</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span></code></pre></div><p><code>dispatch()</code> takes the envelope without <code>id</code> and <code>receivedAt</code>; it fills in a random UUID and the current time. <code>trigger</code> is the trigger id (<code>&#39;http&#39;</code>, <code>&#39;webhook:/issues&#39;</code>, ...). <code>source</code> is one of <code>cron</code>, <code>http</code>, <code>webhook</code>, <code>github</code> or <code>mcp</code> (a run started through <code>http()</code> over MCP has <code>trigger: &#39;http&#39;</code> and <code>source: &#39;mcp&#39;</code>).</p><p>The engine renders the source, trigger id and payload as a JSON block and makes it the run&#39;s first user message. The model sees exactly that; put what it needs into the payload.</p><p><code>thread</code> is stored on the run. Loading the history of earlier runs of the same thread is planned for the mail digest milestone.</p><h2 id="idempotency-keys" tabindex="-1">Idempotency keys <a class="header-anchor" href="#idempotency-keys" aria-label="Permalink to &quot;Idempotency keys&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> first = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    trigger: </span><span style="color:#E7C58C;">&#39;webhook:/issues&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#E6DFDE;">, issue: </span><span style="color:#E7C58C;">42</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#958A8B;">    // a redelivery with the same key returns the same run</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey: </span><span style="color:#E7C58C;">&#39;delivery-7f3a&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // one run at a time per issue</span></span>
<span class="line"><span style="color:#E6DFDE;">    concurrencyKey: </span><span style="color:#E7C58C;">&#39;acme/app#42&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> again = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    trigger: </span><span style="color:#E7C58C;">&#39;webhook:/issues&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#E6DFDE;">, issue: </span><span style="color:#E7C58C;">42</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey: </span><span style="color:#E7C58C;">&#39;delivery-7f3a&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6DFDE;">again.runId === first.runId; </span><span style="color:#958A8B;">// true</span></span>
<span class="line"><span style="color:#E6DFDE;">again.deduplicated; </span><span style="color:#958A8B;">// true</span></span></code></pre></div><p>With an <code>idempotencyKey</code>, <code>dispatch()</code> claims the key in the store under the scope <code>&lt;agent&gt;:&lt;source&gt;</code> (for example <code>triage:webhook</code>) for 7 days. The first dispatch creates the run. Every later dispatch with the same agent, source and key returns the existing run id with <code>deduplicated: true</code>, and no new run is created.</p><p>Use a key that is stable across redeliveries: a GitHub delivery id, a cron job plus its scheduled time, or a key your client sends.</p><p>If the store claimed the key but the run was never created (for example <code>createRun</code> failed right after the claim), the next dispatch with that key creates the run under the reserved id. <code>createRun</code> is insert-if-absent, so concurrent dispatches create it once.</p><h2 id="concurrency-keys" tabindex="-1">Concurrency keys <a class="header-anchor" href="#concurrency-keys" aria-label="Permalink to &quot;Concurrency keys&quot;">​</a></h2><p>A run with a <code>concurrencyKey</code> starts only when no other run of the same agent with the same key is <code>running</code>, <code>waiting</code> or <code>interrupted</code>. Runs with different keys, and runs without a key, run in parallel up to the engine&#39;s <code>maxConcurrentRuns</code>. See <a href="/guide/concurrency">Concurrency, Leases &amp; Multi-Replica</a>.</p><p>Typical keys: one per repository, issue or pull request (<code>acme/app#42</code>), or one per mailbox.</p>`,21)])])}const E=s(t,[["render",p]]);export{h as __pageData,E as default};
